head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_SecuGrpId; // 증권그룹ID
scwin.fr_SearchTyp; // 예비심사종목을 조회할지, 신규상장종목을 조회할지의 구분값
scwin.fr_mktTpCd; // 유가종목, 코스닥종목, 유가+코스닥전체종목 조회구분값

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        window.document.body.scroll = "no";
        let arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        // alert('[fr_SearchTyp]'+fr_SearchTyp);

        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
            strSch = (arrPar.length >= 1 ? arrPar[0] : "");
            scwin.fr_SecuGrpId = (arrPar.length >= 3 ? arrPar[2] : "");
            scwin.fr_mktTpCd = (arrPar.length >= 4 ? arrPar[3] : "");
            scwin.fr_SearchTyp = (arrPar.length >= 5 ? arrPar[4] : "");
        }
        txb_Search.focus();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name dts_IsurInst_OnLoadError
 * @description dts_IsurInst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsurInst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_IsurInst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.dts_IsurInst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IsurInst_OnLoadCompleted
 * @description dts_IsurInst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsurInst_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_IsurInst.errorMsg) {
            await $c.win.alert(dts_IsurInst.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");

            // 초기1회 초기값으로 설정된 회사코드를 검색한다.
            if (scwin.strCdSch !== "") {
                for (let i = 1; i <= dts_IsurInst.getRowCount(); i++) {
                    if (scwin.strCdSch === dts_IsurInst.getCellData(i, 1)) {
                        dts_IsurInst.setRowPosition(i, 0);
                        break;
                    }
                }
                scwin.strCdSch = "";
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.dts_IsurInst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_IsuInst_OnDblClick
 * @description grd_IsuInst 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = {
                ISUR_CD: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "ISUR_CD"),
                COM_NM: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "COM_NM"),
                COM_ENG_NM: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "COM_ENG_NM"),
                CNTR_ISO_CD: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "CNTR_ISO_CD"),
                CNTR_ISO_NM: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "CNTR_ISO_NM"),
                BZ_PROCS_NO: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "BZ_PROCS_NO"), // 신규상장에서 사용할값.
                DBCLICKYN: "Y",
                HPAGE: dts_IsurInst.getCellData(dts_IsurInst.getRowPosition(), "HPAGE")
            };
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.grd_IsuInst_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05011.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (scwin.fr_mktTpCd === "6") {
        url += "?SCREN_ID=" + "ULDSTF05011.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=PRELISTING_ISUR_INST_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.konex.select.newlisting.newreg.corp.condition" + "&{P}param01=" + txb_Search.getValue(); // 법인코드
        const sbmOptions = {
            id : "sbm_dts_IsurInst",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_IsurInst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        url += "&COM_NM=" + txb_Search.getValue();
        url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
        url += "&SEARCH_TYP=" + scwin.fr_SearchTyp;
        url += "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.fr_mktTpCd;
        const sbmOptions = {
            id : "sbm_dts_IsurInst",
            action : "/Prelisting.do",
            ref : "",
            target : "dts_IsurInst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};
